package com.app.entity;
import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime;
@Entity @Table(name="society_complaints") @Data @Builder @NoArgsConstructor @AllArgsConstructor
public class SocietyComplaint {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="account_id",nullable=false) private Account account; @Column(nullable=false,length=30) private String complaintNumber; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="flat_id",nullable=false) private Flat flat; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="complainant_user_id",nullable=false) private User complainant; @Column(nullable=false) private String complainantName; @Column(nullable=false,length=180) private String title; @Column(nullable=false,length=2000) private String description; @Column(nullable=false,length=30) private String category; @Column(nullable=false,length=20) @Builder.Default private String priority="NORMAL"; @Column(nullable=false,length=20) @Builder.Default private String status="OPEN"; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="work_order_id") private SocietyWorkOrder workOrder; private LocalDateTime acknowledgedAt; private LocalDateTime resolvedAt; @Column(nullable=false,updatable=false) @Builder.Default private LocalDateTime createdAt=LocalDateTime.now(); @Column(nullable=false) @Builder.Default private LocalDateTime updatedAt=LocalDateTime.now(); @PreUpdate void touch(){updatedAt=LocalDateTime.now();}}
